Tile("hello-there", {
  css: ".hi{display:flex;flex-direction:column;justify-content:center;height:100%} .hi b{font-size:44px;color:var(--accent)} .hi small{color:var(--dim);font-size:20px}",
  cls: "hi",
  render(el){
    const t = new Date();
    el.innerHTML = "<b>Hello there</b><div>" + this.esc(t.toLocaleTimeString([], {hour:"numeric", minute:"2-digit"})) + "</div><small>Version 2</small>";
  }
});

Tile("moon-facts", {
  css: ".mf b{color:var(--accent)} .mf .n{font-size:40px}",
  cls: "mf",
  render(el){
    const fact = this.fetch("https://api.example.com/moon.json", 300), err = this.fetchError("https://api.example.com/moon.json");
    const wx = this.feed("weather"), n = (this.store.get().taps || 0);
    el.innerHTML = "<h3>" + this.esc(this.name) + "</h3><div class=fact>" + (fact ? this.esc(fact.fact) : err ? "Couldn't load: " + this.esc(err) : "Loading…") +
      "</div><div class=wx>" + (wx && wx.current ? "Weather here" : "No weather") + "</div><div class=n>" + this.esc(this.s.label) + ": <b>" + n + "</b></div>";
  },
  tap(){ this.store.set("taps", (this.store.get().taps || 0) + 1); }
});

Tile("list-count", {
  css: ".lcnt{display:flex;flex-direction:column;justify-content:center;height:100%} .lcnt b{font-size:56px;color:var(--accent)}",
  cls: "lcnt",
  render(el){
    const n = this.feed("notes"), items = Array.isArray(n) ? n : n && typeof n === "object" ? [].concat(...Object.values(n).filter(Array.isArray)) : [];
    el.innerHTML = "<h3>" + this.esc(this.name) + "</h3><b>" + items.length + "</b><div>on your lists</div>";
  }
});

Tile("front-porch", {
  render(el){
    const d = this.devices(), light = d.light, lock = d.lock;
    const line = (o, what) => "<div class=li><span class=s>" + this.esc(what) + "</span><span class=t data-dev>" + this.esc(o ? o.state : "not picked") + "</span></div>";
    el.innerHTML = "<h3>" + this.esc(this.name) + "</h3>" + line(light, "Light") + line(lock, "Lock") +
      "<div class=tried>" + this.esc(this._tried || "") + "</div><div class=keys>" + this.esc(Object.keys(this.s).join(",")) + "</div>";
  },
  // tap the tile: its code tries every way to work the lock by itself. None of them may do anything
  tap(e, root){
    const tries = [];
    this.act("tile.control", {control:"unlock"}).then(() => tries.push("act worked"), () => tries.push("act refused"));
    parent.postMessage({ct:"control", id:"unlock"}, "*");
    parent.postMessage({ct:"act", action:"tile.control", args:{control:"unlock"}}, "*");
    try { parent.document.querySelector("[data-sbxc]").click(); tries.push("clicked the dashboard"); } catch (e) { tries.push("can't reach the dashboard"); }
    setTimeout(() => { this._tried = tries.join(", "); root.querySelector(".tried").textContent = this._tried; }, 50);
  }
});
